// Generated by retro + bun. Figma's Glass effect on phones: the content behind
// the glass is snapshotted, bent at the edges (Refraction, Depth), split into
// colours at the rim (Dispersion), frosted (Frost) and lit (Light).
import { useCallback, useEffect, useRef, useState, type ComponentRef, type RefObject } from 'react';
import { PixelRatio, StyleSheet, View } from 'react-native';
import { Blur, Canvas, Fill, Group, ImageShader, Shader, Skia, makeImageFromView, rect, rrect, type SkImage } from '@shopify/react-native-skia';

const SKSL = `
uniform shader image;
uniform float2 size;
uniform float2 offset;
uniform float scale;
uniform float radius;
uniform float refraction;
uniform float depth;
uniform float dispersion;
uniform float lightAngle;
uniform float lightIntensity;
uniform float splay;
uniform float mode;

float sdBox(float2 p, float2 b, float r) {
  float2 q = abs(p) - b + float2(r, r);
  return length(max(q, float2(0.0, 0.0))) + min(max(q.x, q.y), 0.0) - r;
}

half4 main(float2 xy) {
  float2 hs = size * 0.5;
  float2 p = xy - hs;
  float r = min(radius, min(hs.x, hs.y));
  float d = sdBox(p, hs, r);
  float dx = sdBox(p + float2(1.0, 0.0), hs, r) - sdBox(p - float2(1.0, 0.0), hs, r);
  float dy = sdBox(p + float2(0.0, 1.0), hs, r) - sdBox(p - float2(0.0, 1.0), hs, r);
  float2 n = normalize(float2(dx, dy) + float2(0.00001, 0.00001));
  // Splay: how far the bending spreads in from the rim, and how softly.
  float band = max(depth, 1.0) * (1.0 + splay * 1.5);
  float edge = clamp(1.0 + d / band, 0.0, 1.0);
  float bend = pow(edge, mix(4.0, 2.0, splay)) * refraction * band;
  if (mode < 0.5) {
    float2 base = (xy + offset - n * bend) * scale;
    float2 ca = n * dispersion * bend * 0.4 * scale;
    half rr = image.eval(base + ca).r;
    half gg = image.eval(base).g;
    half bb = image.eval(base - ca).b;
    return half4(rr, gg, bb, 1.0);
  }
  float2 L = float2(cos(lightAngle), -sin(lightAngle));
  float lit = max(dot(n, L), 0.0);
  float back = max(dot(n, -L), 0.0);
  float a = clamp(pow(edge, 6.0) * (lit + back * 0.4) * lightIntensity * 1.3, 0.0, 1.0);
  return half4(a, a, a, a);
}
`;

// CanvasKit isn't loaded during web/static rendering, so Make() can throw.
const effect = (() => {
  try {
    return Skia.RuntimeEffect.Make(SKSL);
  } catch {
    return null;
  }
})();
if (!effect) console.warn('[LiquidGlass] shader failed to compile');

type Host = ComponentRef<typeof View>;

type Props = {
  target: RefObject<Host | null>;
  radius: number;
  refraction: number;
  depth: number;
  dispersion: number;
  frost: number;
  lightAngle: number;
  lightIntensity: number;
  splay?: number;
};

// Resolves null instead of throwing when a view can't be measured.
const measure = (v: Host | null) =>
  new Promise<number[] | null>((res) => {
    if (!v || typeof (v as { measureInWindow?: unknown }).measureInWindow !== 'function') return res(null);
    v.measureInWindow((x, y, w, h) => res([x, y, w, h]));
  });

// Every glass layer on a screen shares the same background, so take one
// snapshot per screen and let all of them reuse it (a screen with 20 glass
// keys used to take 20 full-screen pictures, several times over).
type Shot = { img: SkImage; at: number[] };
const shots = new WeakMap<object, { time: number; shot: Promise<Shot | null> }>();
function snapshotOf(target: RefObject<Host | null>): Promise<Shot | null> {
  const key = target.current as object | null;
  if (!key) return Promise.resolve(null);
  const hit = shots.get(key);
  if (hit && Date.now() - hit.time < 500) return hit.shot;
  const shot = (async () => {
    const at = await measure(target.current);
    if (!at || !at[2] || !at[3]) return null;
    const img = await makeImageFromView(target as never);
    return img ? { img, at } : null;
  })().catch(() => null);
  shots.set(key, { time: Date.now(), shot });
  return shot;
}

export function LiquidGlass({ target, radius, refraction, depth, dispersion, frost, lightAngle, lightIntensity, splay = 0.5 }: Props) {
  const self = useRef<Host>(null);
  const [snap, setSnap] = useState<SkImage | null>(null);
  const [box, setBox] = useState({ x: 0, y: 0, w: 0, h: 0, s: 1 });
  const alive = useRef(true);
  const done = useRef(false);
  const localW = useRef(0); // this view's width in its own (unscaled) points

  // One snapshot attempt; false if the view isn't on screen or laid out yet.
  const capture = useCallback(async () => {
    try {
      const [shot, sp] = await Promise.all([snapshotOf(target), measure(self.current)]);
      if (!shot || !sp || !sp[2] || !sp[3] || !alive.current) return false;
      const { img, at: tp } = shot;
      // The snapshot's own pixels-per-point, so the background inside the
      // glass lines up exactly with the background around it.
      // The screen may be scaled to fit the phone: measurements are in screen
      // points, the canvas draws in this view's own (unscaled) points.
      const k = localW.current > 0 ? sp[2] / localW.current : 1;
      setBox({ x: (sp[0] - tp[0]) / k, y: (sp[1] - tp[1]) / k, w: sp[2] / k, h: sp[3] / k, s: (img.width() * k) / tp[2] });
      setSnap(img);
      done.current = true;
      return true;
    } catch {
      return false;
    }
  }, [target]);

  useEffect(() => {
    alive.current = true;
    // Early tries until one works, then a refresh once images and fonts have
    // loaded. Only warn if the glass never managed a snapshot.
    const ids = [200, 1200].map((ms, i, all) =>
      setTimeout(async () => {
        const ok = await capture();
        if (!ok && i === all.length - 1 && !done.current && alive.current) {
          console.warn('[LiquidGlass] no snapshot of the background; showing the plain frosted fill');
        }
      }, ms),
    );
    return () => {
      alive.current = false;
      ids.forEach(clearTimeout);
    };
  }, [capture]);

  if (!effect) return null;
  const clip = rrect(rect(0, 0, box.w, box.h), radius, radius);
  const uniforms = (mode: number) => ({
    size: [box.w, box.h],
    offset: [box.x, box.y],
    scale: box.s || PixelRatio.get(),
    radius,
    refraction,
    depth,
    dispersion,
    lightAngle: (lightAngle * Math.PI) / 180,
    lightIntensity,
    splay,
    mode,
  });

  return (
    <View ref={self} collapsable={false} pointerEvents="none" style={StyleSheet.absoluteFill} onLayout={(e) => { localW.current = e.nativeEvent.layout.width; capture(); }}>
      {snap && box.w > 0 ? (
        <Canvas style={StyleSheet.absoluteFill}>
          <Group clip={clip}>
            <Fill>
              <Shader source={effect} uniforms={uniforms(0)}>
                <ImageShader image={snap} fit="none" rect={rect(0, 0, snap.width(), snap.height())} />
              </Shader>
              <Blur blur={frost * 0.3} mode="clamp" />
            </Fill>
            <Fill>
              <Shader source={effect} uniforms={uniforms(1)}>
                <ImageShader image={snap} fit="none" rect={rect(0, 0, snap.width(), snap.height())} />
              </Shader>
            </Fill>
          </Group>
        </Canvas>
      ) : null}
    </View>
  );
}
